  private parseEntry(raw: string): { country: string; values: RawValues } | null {
    let parsed: unknown;
    try {
      parsed = JSON.parse(raw);
    } catch {
      return null;
    }
    if (!isRecord(parsed) || parsed['version'] !== VERSION) return null;
    const country = parsed['country'];
    if (typeof country !== 'string' || !/^[A-Z]{2}$/.test(country)) return null;
    const step1 = parsed['step1'];
    if (!isRecord(step1)) return null;
    const stored = step1['values'];
    if (!isRecord(stored)) return null;
    const values: RawValues = {};
    for (const [key, value] of Object.entries(stored)) {
      if (typeof value !== 'string' && typeof value !== 'boolean') return null;
      values[key] = value;
    }
    return { country, values };
  }

  private persist(): void {
    const country = this.countrySignal();
    if (country === null) return;
    try {
      sessionStorage.setItem(STORAGE_KEY, JSON.stringify({ version: VERSION, country, step1: { values: this.valuesSignal() } }));
    } catch {
      this.warnStorageOnce();
    }
  }

  private clearStorage(): void {
    try {
      sessionStorage.removeItem(STORAGE_KEY);
    } catch {
      this.warnStorageOnce();
    }
  }

  private warnStorageOnce(): void {
    if (this.warnedAboutStorage) return;
    this.warnedAboutStorage = true;
    console.warn('quote-wizard: sessionStorage is unavailable, the state is kept in memory only');
  }
}
import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { Observable, map } from 'rxjs';
import { parseFieldConfigs } from '../shared/field-config';
import type { FieldConfig } from '../shared/field-config.model';
import { contentGet } from './content-request';

@Injectable({ providedIn: 'root' })
export class FormFieldApi {
  private readonly http = inject(HttpClient);

  /** One request per country, filtered by the published country code (ADR-0001). */
  list(countryCode: string): Observable<FieldConfig[]> {
    return contentGet(this.http, 'form-fields', {
      'filters[country][code][$eq]': countryCode,
      'populate[options]': 'true',
      'populate[rules]': 'true',
      sort: 'sortOrder:asc',
      'pagination[pageSize]': '100',
    }).pipe(map(parseFieldConfigs));
  }
}
import { HttpClient } from '@angular/common/http';
import { Observable, timeout } from 'rxjs';

/** Limit for every content request: after 10 s the load is treated as failed (US-01-Q-17). */
export const CONTENT_TIMEOUT_MS = 10_000;

/**
 * GET on the same-origin content API (relative `/api`, ADR-0002). Read-only: no body, no
 * Authorization header, and nothing from the wizard state ever goes into the request.
 */
export function contentGet(http: HttpClient, path: string, params: Record<string, string>): Observable<unknown> {
  return http.get<unknown>(`/api/${path}`, { params }).pipe(timeout(CONTENT_TIMEOUT_MS));
}
import { inject } from '@angular/core';
import { CanActivateFn, RedirectCommand, Router } from '@angular/router';
import { CountryStore } from './country-store';
import { FormFieldStore } from './form-field-store';
import { QuoteStore } from './quote-store';

/**
 * Step 2 is reachable only when the wizard state holds step 1 values for the route's country that
 * pass the same validators against this page load's configuration (ADR-0001, US-01-AC-19).
 * Otherwise it redirects to step 1, replacing the blocked address in the history.
 */
export const wizardStepGuard: CanActivateFn = async (route) => {
  const router = inject(Router);
  const countries = inject(CountryStore);
  const fields = inject(FormFieldStore);
  const quote = inject(QuoteStore);

  const param = (route.paramMap.get('country') ?? route.parent?.paramMap.get('country') ?? '').toLowerCase();
  const toStep1 = new RedirectCommand(router.parseUrl(`/${param}/datos`), { replaceUrl: true });

  await countries.ensureLoaded();
  const country = countries.find(param);
  if (!country || quote.country() !== country.code) return toStep1;
  try {
    const configs = await fields.load(country.code);
    return configs.length > 0 && quote.isStep1Valid(configs) ? true : toStep1;
  } catch {
    return toStep1;
  }
};
import { InjectionToken } from '@angular/core';

/** The source of "today" for every validator (US-01-Q-06). Tests provide a fixed one. */
export const CLOCK = new InjectionToken<() => Date>('CLOCK', {
  providedIn: 'root',
  factory: () => () => new Date(),
});
