        key: 'clasico',
        name: 'Plan Clásico',
        shortDescription: 'Cubre los daños a terceros y la pérdida total de tu vehículo.',
        basePrice: 1400000,
        sortOrder: 20,
        isRecommended: true,
        coverages: seedPlan('CO', 'clasico').coverages,
        benefits: seedPlan('CO', 'clasico').benefits,
      });
    });

